import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.File;

/**
 * Draws curseforge/icon.png from scratch: a white border, a blood-wax honeycomb made from a hex grid
 * and noise, and "ENTO / PATCH" in hand-made pixel letters. No font, no Entomophobia asset, nothing
 * generated by AI. Run from the repo root: java curseforge/MakeIcon.java curseforge/icon.png
 */
public class MakeIcon {
    static final int GRID = 52;
    static final int CELL = 10;
    static final int BORDER = 2;
    static final long SEED = 1_1_1_2026L;

    static final int WHITE = 0xFFFFFF;
    static final int OUTLINE = 0x12050A;
    static final int SHADOW = 0x24070F;
    /** Comb walls (wax), dark to light. */
    static final int[] WAX = {0x3A160E, 0x572515, 0x77381C, 0x9A5226};
    /** Cell insides (blood), dark to light, and an empty cell. */
    static final int[] BLOOD = {0x3A0B12, 0x5C1220, 0x7E1B2C, 0x9E2A38, 0xBF4249};
    static final int EMPTY = 0x14060A;
    /** Hex cell radius, in icon pixels. */
    static final double HEX = 5.2;

    static final String[] E = {
            "#######",
            "#######",
            "##.....",
            "##.....",
            "##.....",
            "######.",
            "######.",
            "##.....",
            "##.....",
            "#######",
            "#######"};
    static final String[] P = {
            "######.",
            "#######",
            "##...##",
            "##...##",
            "##...##",
            "#######",
            "######.",
            "##.....",
            "##.....",
            "##.....",
            "##....."};
    static final String[] R = {
            "######.",
            "#######",
            "##...##",
            "##...##",
            "##...##",
            "#######",
            "######.",
            "##.##..",
            "##..##.",
            "##...##",
            "##...##"};
    static final String[] I = {
            "######",
            "######",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "######",
            "######"};
    static final String[] O = {
            ".#####.",
            "#######",
            "##...##",
            "##...##",
            "##...##",
            "##...##",
            "##...##",
            "##...##",
            "##...##",
            "#######",
            ".#####."};
    static final String[] N = {
            "##...##",
            "###..##",
            "###..##",
            "####.##",
            "####.##",
            "##.#.##",
            "##.####",
            "##.####",
            "##..###",
            "##..###",
            "##...##"};
    static final String[] A = {
            ".#####.",
            "#######",
            "##...##",
            "##...##",
            "##...##",
            "#######",
            "#######",
            "##...##",
            "##...##",
            "##...##",
            "##...##"};
    static final String[] T = {
            "######",
            "######",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##.."};
    static final String[] C = {
            ".######",
            "#######",
            "##.....",
            "##.....",
            "##.....",
            "##.....",
            "##.....",
            "##.....",
            "##.....",
            "#######",
            ".######"};
    static final String[] H = {
            "##...##",
            "##...##",
            "##...##",
            "##...##",
            "#######",
            "#######",
            "##...##",
            "##...##",
            "##...##",
            "##...##",
            "##...##"};

    public static void main(String[] args) throws Exception {
        int[][] color = new int[GRID][GRID];
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                color[y][x] = comb(x, y);
            }
        }

        boolean[][] text = new boolean[GRID][GRID];
        int letterGap = 2;
        int lineGap = 4;
        String[][] top = {E, N, T, O};
        String[][] bottom = {P, A, T, C, H};
        int height = 11 + lineGap + 11;
        int y0 = (GRID - height) / 2;
        stamp(text, top, letterGap, y0);
        stamp(text, bottom, letterGap, y0 + 11 + lineGap);

        boolean[][] outline = grow(text);
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                if (x >= 1 && y >= 1 && outline[y - 1][x - 1] && !outline[y][x]) {
                    color[y][x] = SHADOW;
                }
            }
        }
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                if (text[y][x]) {
                    color[y][x] = WHITE;
                } else if (outline[y][x]) {
                    color[y][x] = OUTLINE;
                }
            }
        }

        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                if (x < BORDER || y < BORDER || x >= GRID - BORDER || y >= GRID - BORDER) {
                    color[y][x] = WHITE;
                }
            }
        }

        int scale = args.length > 1 ? 1 : CELL;
        BufferedImage image = new BufferedImage(GRID * scale, GRID * scale, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < GRID * scale; y++) {
            for (int x = 0; x < GRID * scale; x++) {
                image.setRGB(x, y, color[y / scale][x / scale]);
            }
        }
        ImageIO.write(image, "png", new File(args[0]));
    }

    /** A pixel of the honeycomb: wax where it's near a cell's edge, blood (or an empty cell) inside. */
    static int comb(int x, int y) {
        // Pointy-top hex grid: pixel to axial coordinates, rounded through cube coordinates.
        double px = x + 0.5;
        double py = y + 0.5;
        double q = (Math.sqrt(3) / 3 * px - py / 3) / HEX;
        double r = (2.0 / 3 * py) / HEX;
        double cx = q;
        double cz = r;
        double cy = -cx - cz;
        long rx = Math.round(cx);
        long ry = Math.round(cy);
        long rz = Math.round(cz);
        double dx = Math.abs(rx - cx);
        double dy = Math.abs(ry - cy);
        double dz = Math.abs(rz - cz);
        if (dx > dy && dx > dz) {
            rx = -ry - rz;
        } else if (dy > dz) {
            ry = -rx - rz;
        } else {
            rz = -rx - ry;
        }
        // How far from the cell's center, 0 at the center to about 1 at its edge.
        double edge = Math.max(Math.abs(rx - cx), Math.max(Math.abs(ry - cy), Math.abs(rz - cz))) * 2;
        double fromCenter = Math.max(Math.abs(x - (GRID - 1) / 2.0), Math.abs(y - (GRID - 1) / 2.0)) / ((GRID - 1) / 2.0);
        double shade = fbm(x / 9.0, y / 9.0, 0) - Math.max(0.0, fromCenter - 0.6) * 0.9 + (hash(x, y, 2) - 0.5) * 0.1;
        if (edge > 0.8) {
            int index = (int) Math.floor(shade * 4.4 - 0.2);
            return WAX[Math.max(0, Math.min(WAX.length - 1, index))];
        }
        double cell = hash((int) rx, (int) rz, 7);
        if (cell < 0.16) {
            return EMPTY;
        }
        int index = (int) Math.floor((shade * 0.8 + cell * 0.35) * 5.0 - 1.2 + (edge < 0.25 ? 0.6 : 0.0));
        return BLOOD[Math.max(0, Math.min(BLOOD.length - 1, index))];
    }

    static void stamp(boolean[][] mask, String[][] letters, int gap, int y0) {
        int width = 0;
        for (String[] letter : letters) {
            width += letter[0].length();
        }
        width += gap * (letters.length - 1);
        int x = (GRID - width) / 2;
        for (String[] letter : letters) {
            for (int row = 0; row < letter.length; row++) {
                for (int col = 0; col < letter[row].length(); col++) {
                    if (letter[row].charAt(col) == '#') {
                        mask[y0 + row][x + col] = true;
                    }
                }
            }
            x += letter[0].length() + gap;
        }
    }

    /** The mask plus every cell next to it, diagonals included. */
    static boolean[][] grow(boolean[][] mask) {
        boolean[][] out = new boolean[GRID][GRID];
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                for (int dy = -1; dy <= 1 && !out[y][x]; dy++) {
                    for (int dx = -1; dx <= 1; dx++) {
                        int nx = x + dx;
                        int ny = y + dy;
                        if (nx >= 0 && ny >= 0 && nx < GRID && ny < GRID && mask[ny][nx]) {
                            out[y][x] = true;
                            break;
                        }
                    }
                }
            }
        }
        return out;
    }

    static double fbm(double x, double y, int layer) {
        double sum = 0;
        double amplitude = 0.5;
        double total = 0;
        for (int octave = 0; octave < 4; octave++) {
            sum += amplitude * noise(x, y, layer * 16 + octave);
            total += amplitude;
            x *= 2.0;
            y *= 2.0;
            amplitude *= 0.5;
        }
        return sum / total;
    }

    /** Smoothly interpolated value noise in 0..1. */
    static double noise(double x, double y, int layer) {
        int x0 = (int) Math.floor(x);
        int y0 = (int) Math.floor(y);
        double fx = x - x0;
        double fy = y - y0;
        double sx = fx * fx * (3 - 2 * fx);
        double sy = fy * fy * (3 - 2 * fy);
        double a = hash(x0, y0, layer);
        double b = hash(x0 + 1, y0, layer);
        double c = hash(x0, y0 + 1, layer);
        double d = hash(x0 + 1, y0 + 1, layer);
        return (a + (b - a) * sx) * (1 - sy) + (c + (d - c) * sx) * sy;
    }

    static double hash(int x, int y, int layer) {
        long h = SEED ^ (x * 0x9E3779B97F4A7C15L) ^ (y * 0xC2B2AE3D27D4EB4FL) ^ (layer * 0x165667B19E3779F9L);
        h ^= h >>> 33;
        h *= 0xFF51AFD7ED558CCDL;
        h ^= h >>> 33;
        h *= 0xC4CEB9FE1A85EC53L;
        h ^= h >>> 33;
        return (h >>> 11) / (double) (1L << 53);
    }
}
